arguments.command:
python3 - <<'EOF'
d=open('/app/trunc.db','rb').read()
# find all nonzero regions
import re
regs=[]
start=None
for i,b in enumerate(d):
    if b: 
        if start is None: start=i
    else:
        if start is not None and i-start>0:
            regs.append((start,i)); start=None
if start is not None: regs.append((start,len(d)))
# merge close
m=[]
for s,e in regs:
    if m and s-m[-1][1]<8: m[-1]=(m[-1][0],e)
    else: m.append((s,e))
for s,e in m: print(hex(s),hex(e),d[s:e][:80])
EOF

